var APY=Object.assign(window.APY||{},{"13世纪的中国":"Shísān shìjì de Zhōngguó","《马可·波罗游记》介绍了什么内容？":"《Mǎkě·Bōluó Yóujì》 jièshàole shénme nèiróng?","一点儿":"Yìdiǎnr","下周六晚上，我请大家去国家大剧院看京剧，怎么样？":"Xià zhōuliù wǎnshang, wǒ qǐng dàjiā qù Guójiā Dàjùyuàn kàn Jīngjù, zěnmeyàng?","下周六晚上，李文请大家去做什么？":"Xià zhōuliù wǎnshang, Lǐ Wén qǐng dàjiā qù zuò shénme?","不是……，就是……":"Bú shì ……, jiù shì ……","不知道我们能不能看懂。":"Bù zhīdào wǒmen néng bu néng kàndǒng.","两天":"Liǎng tiān","中国的教育":"Zhōngguó de jiāoyù","中国的经济":"Zhōngguó de jīngjì","了解中国国粹之一——京剧。":"Liǎojiě Zhōngguó guócuì zhī yī —— Jīngjù.","了解了":"Liǎojiěle","作品":"Zuòpǐn","作品/作者/作家/读者":"Zuòpǐn / zuòzhě / zuòjiā / dúzhě","作家":"Zuòjiā","你喜欢看什么书？":"Nǐ xǐhuan kàn shénme shū?","你过生日时会怎么庆祝？":"Nǐ guò shēngrì shí huì zěnme qìngzhù?","先做做功课":"Xiān zuòzuo gōngkè","内容很幽默":"Nèiróng hěn yōumò","内心":"Nèixīn","再买一本送给朋友":"Zài mǎi yì běn sòng gěi péngyou","到家后":"Dào jiā hòu","功课":"Gōngkè","去意大利玩":"Qù Yìdàlì wán","周六，李文和白家月、安妮、陈天中视频通话。":"Zhōuliù, Lǐ Wén hé Bái Jiāyuè, Ānnī, Chén Tiānzhōng shìpín tōnghuà.","咱们先做做功课，提前了解下，能懂一点儿是一点儿。":"Zánmen xiān zuòzuo gōngkè, tíqián liǎojiě xià, néng dǒng yìdiǎnr shì yìdiǎnr.","回答问题":"Huídá wèntí","在家里，王一雪和刘小雪谈小雪学校艺术节节目排练情况。":"Zài jiā li, Wáng Yīxuě hé Liú Xiǎoxuě tán Xiǎoxuě xuéxiào yìshùjié jiémù páiliàn qíngkuàng.","基本上排好了":"Jīběnshàng pái hǎo le","好啊。我小时候在加拿大度假时，在宾馆的电视上看过一次，是梅兰芳等演员演的，演员们都非常棒，他们演唱得好听极了，给我留下的印象特别深。":"Hǎo a. Wǒ xiǎoshíhou zài Jiānádà dùjià shí, zài bīnguǎn de diànshì shang kàn guo yí cì, shì Méi Lánfāng děng yǎnyuán yǎn de, yǎnyuánmen dōu fēicháng bàng, tāmen yǎnchàng de hǎotīng jí le, gěi wǒ liúxia de yìnxiàng tèbié shēn.","好的，我同学演少年歌手，他的歌声美极了。我演他的妈妈，不知道像不像呢。":"Hǎo de, wǒ tóngxué yǎn shàonián gēshǒu, tā de gēshēng měi jí le. Wǒ yǎn tā de māma, bù zhīdào xiàng bu xiàng ne.","好的，谢谢妈妈！":"Hǎo de, xièxie māma!","如果你来越南，……":"Rúguǒ nǐ lái Yuènán, ……","学京剧动作":"Xué Jīngjù dòngzuò","学唱京剧":"Xué chàng Jīngjù","它的特点是……":"Tā de tèdiǎn shì ……","完成作业":"Wánchéng zuòyè","完成自己的作品":"Wánchéng zìjǐ de zuòpǐn","对，我先去网上查资料，查完后也转发给你们。":"Duì, wǒ xiān qù wǎngshang chá zīliào, cháwán hòu yě zhuǎnfā gěi nǐmen.","小雪和同学们的话剧排得怎么样了？":"Xiǎoxuě hé tóngxuémen de huàjù pái de zěnmeyàng le?","小雪的同学唱歌怎么样？":"Xiǎoxuě de tóngxué chànggē zěnmeyàng?","小雪，你们的话剧排好了吗？":"Xiǎoxuě, nǐmen de huàjù pái hǎo le ma?","差不多了，妈妈。艺术节周五下午开始，我内心还是有些紧张，有时候不是忘词，就是忘记做动作。":"Chàbuduō le, māma. Yìshùjié zhōuwǔ xiàwǔ kāishǐ, wǒ nèixīn háishi yǒuxiē jǐnzhāng, yǒu shíhou bú shì wàng cí, jiù shì wàngjì zuò dòngzuò.","庆祝":"Qìngzhù","庆祝演出成功":"Qìngzhù yǎnchū chénggōng","度假":"Dùjià","很有感情":"Hěn yǒu gǎnqíng","很爱忘词":"Hěn ài wàng cí","忘记做动作":"Wàngjì zuò dòngzuò","忘词":"Wàng cí","我又":"Wǒ yòu","我和你爸":"Wǒ hé nǐ bà","我喜欢的一种艺术形式":"Wǒ xǐhuan de yì zhǒng yìshù xíngshì","我喜欢的一部小说":"Wǒ xǐhuan de yí bù xiǎoshuō","我喜欢看小说，特别是历史小说。最近我在看中文版的《西游记》，虽然有点儿难，但是很有意思。":"Wǒ xǐhuan kàn xiǎoshuō, tèbié shì lìshǐ xiǎoshuō. Zuìjìn wǒ zài kàn Zhōngwén bǎn de 《Xīyóu Jì》, suīrán yǒudiǎnr nán, dànshì hěn yǒu yìsi.","我最喜欢的艺术形式是……":"Wǒ zuì xǐhuan de yìshù xíngshì shì ……","我第一次看是……，给我留下了……的印象":"Wǒ dì-yī cì kàn shì ……, gěi wǒ liúxiale …… de yìnxiàng","把它翻译给家人":"Bǎ tā fānyì gěi jiārén","把故事":"Bǎ gùshi","把这本书":"Bǎ zhè běn shū","报考":"Bàokǎo","排好了":"Pái hǎo le","提前了解":"Tíqián liǎojiě","故事有意思":"Gùshi yǒu yìsi","整理":"Zhěnglǐ","文字":"Wénzì","文章":"Wénzhāng","是":"Shì","有时候":"Yǒu shíhou","期待":"Qīdài","李文他们":"Lǐ Wén tāmen","李文很期待那场演出，因为：":"Lǐ Wén hěn qīdài nà chǎng yǎnchū, yīnwèi:","梅兰芳先生是中国著名京剧艺术家。咱们要看的这个京剧是青年演员们演的，要去看的观众也特别多。":"Méi Lánfāng xiānsheng shì Zhōngguó zhùmíng Jīngjù yìshùjiā. Zánmen yào kàn de zhège Jīngjù shì qīngnián yǎnyuánmen yǎn de, yào qù kàn de guānzhòng yě tèbié duō.","比较一般":"Bǐjiào yìbān","没事，妈妈相信你一定可以。放松些，再自信些！":"Méi shì, māma xiāngxìn nǐ yídìng kěyǐ. Fàngsōng xiē, zài zìxìn xiē!","没问题的，努力做最好的自己就好。演出时，我和你爸都去给你加油。":"Méi wèntí de, nǔlì zuò zuì hǎo de zìjǐ jiù hǎo. Yǎnchū shí, wǒ hé nǐ bà dōu qù gěi nǐ jiāyóu.","演出时":"Yǎnchū shí","演出结束后，演员们邀请观众一起做什么？":"Yǎnchū jiéshù hòu, yǎnyuánmen yāoqǐng guānzhòng yìqǐ zuò shénme?","演员":"Yǎnyuán","演员很专业":"Yǎnyuán hěn zhuānyè","点头":"Diǎntóu","特别好听":"Tèbié hǎotīng","现在的中国":"Xiànzài de Zhōngguó","留下":"Liúxia","白家月的日记":"Bái Jiāyuè de rìjì","白家月看完中文版的《马可·波罗游记》之后打算做什么？":"Bái Jiāyuè kànwán Zhōngwén bǎn de 《Mǎkě·Bōluó Yóujì》 zhīhòu dǎsuàn zuò shénme?","白家月说的“做功课”最可能是什么意思？":"Bái Jiāyuè shuō de “zuò gōngkè” zuì kěnéng shì shénme yìsi?","看了":"Kànle","看京剧":"Kàn Jīngjù","看电影":"Kàn diànyǐng","精彩的演出":"Jīngcǎi de yǎnchū","给你":"Gěi nǐ","继续演节目":"Jìxù yǎn jiémù","翻译内容":"Fānyì nèiróng","能够口头或书面介绍一部作品或一种艺术形式。":"Nénggòu kǒutóu huò shūmiàn jièshào yí bù zuòpǐn huò yì zhǒng yìshù xíngshì.","能够听懂并交流文学、艺术方面的话题。":"Nénggòu tīngdǒng bìng jiāoliú wénxué, yìshù fāngmiàn de huàtí.","能懂一点儿":"Néng dǒng yìdiǎnr","自信":"Zìxìn","艺术":"Yìshù","获奖":"Huòjiǎng","观众":"Guānzhòng","话剧":"Huàjù","谢谢天中！":"Xièxie Tiānzhōng!","转发":"Zhuǎnfā","还差很多":"Hái chà hěn duō","还没开始排":"Hái méi kāishǐ pái","邀请":"Yāoqǐng","那我就在网上订票了，到时候咱们在大剧院入口见。":"Nà wǒ jiù zài wǎngshang dìng piào le, dào shíhou zánmen zài dà jùyuàn rùkǒu jiàn.","都去":"Dōu qù","音乐很好听":"Yīnyuè hěn hǎotīng","鼓掌":"Gǔzhǎng"});
